import Foundation

/// §10.1's registration ceremony as bytes: the credential id and public key a new passkey's
/// `attestationObject` carries — the Swift half of `protocol/src/webauthn.ts`'s
/// `parseAttestedCredential`, held to the same fixture (`protocol/fixtures/webauthn.json`, generated by
/// a THIRD implementation). The Mac app creates a root natively since 2026-10-06
/// (`docs/e2e.md`, "The Mac's own passkey ceremony"), and a registration is the ONE moment a passkey
/// hands out its public key — an assertion returns none, so a root descriptor can only be built here.
public enum WebAuthnRegistration {

    public struct AttestedCredential: Equatable, Sendable {
        public let credentialID: [UInt8]
        /// The 65-byte uncompressed SEC1 point §10.1 stores in the root descriptor.
        public let publicKey: [UInt8]
        public let flags: UInt8
    }

    static let flagUserVerified: UInt8 = 0x04
    static let flagAttestedCredential: UInt8 = 0x40
    static let coseES256 = -7

    /// The credential a registration made, or nil. **Derived from the bytes**, as the browser does:
    /// two paths to the one value that defines an identity are two chances to disagree about it.
    public static func parseAttestedCredential(_ attestationObject: [UInt8]) -> AttestedCredential? {
        guard let outer = CBOR.decode(attestationObject), case .map(let entries) = outer.value,
              case .bytes(let authData)? = entries.first(where: { $0.key == .text("authData") })?.value
        else { return nil }
        return parseAuthenticatorData(authData)
    }

    /// `rpIdHash(32) || flags(1) || signCount(4) || aaguid(16) || credIdLen(2) || credId || COSE_Key`
    public static func parseAuthenticatorData(_ authData: [UInt8]) -> AttestedCredential? {
        guard authData.count >= 37 else { return nil }
        let flags = authData[32]
        // AT: attested credential data present. Without it there is nothing to read, and reading on
        // regardless would interpret whatever follows as a key.
        guard flags & flagAttestedCredential != 0, authData.count >= 37 + 16 + 2 else { return nil }
        let credIDLength = Int(authData[53]) << 8 | Int(authData[54])
        let credStart = 55
        guard authData.count >= credStart + credIDLength else { return nil }
        let credentialID = Array(authData[credStart ..< credStart + credIDLength])
        guard let cose = CBOR.decode(Array(authData[(credStart + credIDLength)...])),
              case .map(let key) = cose.value,
              let publicKey = sec1(fromCOSEKey: key) else { return nil }
        return AttestedCredential(credentialID: credentialID, publicKey: publicKey, flags: flags)
    }

    /// The root descriptor a registration made under `rpID`, or nil. Also refuses a registration whose
    /// `rpIdHash` is another relying party's, or that was not user-verified (§10.4 requires it of every
    /// root ceremony) — the browser leaves the first to the browser; native code is told nothing.
    public static func root(fromAttestationObject attestationObject: [UInt8], rpID: String) -> [UInt8]? {
        guard let outer = CBOR.decode(attestationObject), case .map(let entries) = outer.value,
              case .bytes(let authData)? = entries.first(where: { $0.key == .text("authData") })?.value,
              authData.count >= 37,
              Array(authData[0 ..< 32]) == E2EIdentity.sha256(Array(rpID.utf8)),
              let credential = parseAuthenticatorData(authData),
              credential.flags & flagUserVerified != 0 else { return nil }
        return E2EIdentity.root(rpID: rpID, credentialID: credential.credentialID,
                                rootPublicKey: credential.publicKey)
    }

    /// COSE_Key -> the 65-byte uncompressed SEC1 point: `kty` EC2, `alg` ES256, `crv` P-256 and both
    /// coordinates exactly 32 bytes, every one checked — a key of another curve read as P-256 is a
    /// point that verifies nothing.
    static func sec1(fromCOSEKey key: [(key: CBOR.Value, value: CBOR.Value)]) -> [UInt8]? {
        func get(_ label: Int) -> CBOR.Value? { key.first(where: { $0.key == .int(label) })?.value }
        guard get(1) == .int(2), get(3) == .int(coseES256), get(-1) == .int(1),
              case .bytes(let x)? = get(-2), case .bytes(let y)? = get(-3),
              x.count == 32, y.count == 32 else { return nil }
        return [0x04] + x + y
    }

    /// The CBOR subset WebAuthn uses: unsigned and negative integers, byte and text strings, arrays and
    /// maps. **Deliberately not a general decoder** — tags, floats, indefinite lengths and 64-bit
    /// arguments are REFUSED rather than skipped, and a duplicate map key is a rejection (two decoders
    /// can disagree about which copy wins), exactly as `decodeCbor` does.
    enum CBOR {
        indirect enum Value: Equatable {
            case int(Int), bytes([UInt8]), text(String), array([Value])
            case map([(key: Value, value: Value)])

            static func == (a: Value, b: Value) -> Bool {
                switch (a, b) {
                case let (.int(x), .int(y)): return x == y
                case let (.bytes(x), .bytes(y)): return x == y
                case let (.text(x), .text(y)): return x == y
                case let (.array(x), .array(y)): return x == y
                case let (.map(x), .map(y)):
                    return x.count == y.count && zip(x, y).allSatisfy { $0.key == $1.key && $0.value == $1.value }
                default: return false
                }
            }
        }

        static func decode(_ bytes: [UInt8]) -> (value: Value, length: Int)? {
            guard let item = read(bytes, 0) else { return nil }
            return (item.value, item.next)
        }

        private static func head(_ b: [UInt8], _ at: Int) -> (major: UInt8, arg: Int, next: Int)? {
            guard at < b.count else { return nil }
            let major = b[at] >> 5, minor = b[at] & 0x1f
            switch minor {
            case 0 ..< 24: return (major, Int(minor), at + 1)
            case 24:
                guard at + 1 < b.count else { return nil }
                return (major, Int(b[at + 1]), at + 2)
            case 25:
                guard at + 2 < b.count else { return nil }
                return (major, Int(b[at + 1]) << 8 | Int(b[at + 2]), at + 3)
            case 26:
                guard at + 4 < b.count else { return nil }
                return (major, Int(b[at + 1]) << 24 | Int(b[at + 2]) << 16 | Int(b[at + 3]) << 8 | Int(b[at + 4]), at + 5)
            // 27 is a 64-bit argument and 31 indefinite length: decisions a parser of adversary bytes
            // should not be making.
            default: return nil
            }
        }

        private static func read(_ b: [UInt8], _ at: Int) -> (value: Value, next: Int)? {
            guard let (major, arg, next) = head(b, at) else { return nil }
            switch major {
            case 0: return (.int(arg), next)
            case 1: return (.int(-1 - arg), next)
            case 2:
                guard next + arg <= b.count else { return nil }
                return (.bytes(Array(b[next ..< next + arg])), next + arg)
            case 3:
                guard next + arg <= b.count,
                      let s = String(validating: b[next ..< next + arg], as: UTF8.self) else { return nil }
                return (.text(s), next + arg)
            case 4:
                var out: [Value] = [], cursor = next
                for _ in 0 ..< arg {
                    guard let item = read(b, cursor) else { return nil }
                    out.append(item.value); cursor = item.next
                }
                return (.array(out), cursor)
            case 5:
                var out: [(key: Value, value: Value)] = [], cursor = next
                for _ in 0 ..< arg {
                    guard let k = read(b, cursor), let v = read(b, k.next),
                          !out.contains(where: { $0.key == k.value }) else { return nil }
                    out.append((k.value, v.value)); cursor = v.next
                }
                return (.map(out), cursor)
            default: return nil       // 6 (tags) and 7 (simple/float) are refused, not skipped
            }
        }
    }
}
